import { QueryClient, dehydrate, HydrationBoundary } from '@tanstack/react-query';

async function Page({ params }: { params: { id: string } }) {
  const queryClient = new QueryClient({
    defaultOptions: {
      queries: {
        staleTime: 1000 * 60 * 5
      }
    }
  });

  await queryClient.prefetchQuery({
    queryKey: ['todos', params.id],
    queryFn: () => fetchTodos(params.id)
  });

  return (
    <HydrationBoundary state={dehydrate(queryClient)}>
      <TodoDetail id={params.id} />
    </HydrationBoundary>
  );
}

async function DashboardPage() {
  const queryClient = new QueryClient();

  await Promise.all([
    queryClient.prefetchQuery({ queryKey: ['revenue'], queryFn: fetchRevenue }),
    queryClient.prefetchQuery({ queryKey: ['users'], queryFn: fetchUsers }),
    queryClient.prefetchQuery({ queryKey: ['orders'], queryFn: fetchOrders })
  ]);

  return (
    <HydrationBoundary state={dehydrate(queryClient)}>
      <DashboardClient />
    </HydrationBoundary>
  );
}

async function ProductPage({ params }: { params: { id: string } }) {
  const queryClient = new QueryClient();

  // Hydrate critical above-the-fold data
  await queryClient.prefetchQuery({
    queryKey: ['product', params.id],
    queryFn: () => fetchProduct(params.id)
  });

  // Skip hydrating reviews; fetch client-side
  // await queryClient.prefetchQuery({ queryKey: ['reviews', params.id], ... });

  return (
    <HydrationBoundary state={dehydrate(queryClient)}>
      <ProductClient id={params.id} />
    </HydrationBoundary>
  );
}

// React Component Example with Hooks
import React, { useState, useEffect, useCallback } from 'react';

function DataFetcher({ endpoint }) {
  // State management with useState
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  // useCallback for memoized fetch function
  const fetchData = useCallback(async () => {
    try {
      setLoading(true);
      setError(null);

      const response = await fetch(endpoint);
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      const result = await response.json();
      setData(result);
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  }, [endpoint]);

  // useEffect for side effects
  useEffect(() => {
    fetchData();
  }, [fetchData]);

  if (loading) return <div className="loading">Loading...</div>;
  if (error) return <div className="error">Error: {error}</div>;

  return (
    <div className="data-container">
      <h2>Fetched Data</h2>
      <pre>{JSON.stringify(data, null, 2)}</pre>
    </div>
  );
}

export default DataFetcher;

